#include <bits/stdc++.h>
using namespace std;

double calculateAngle(const vector<int>& p1, const vector<int>& p2, const vector<int>& p3) {
    double dot = 0.0, lenA = 0.0, lenB = 0.0;
    for (int i = 0; i < 5; i++) {
        double v1 = p2[i] - p1[i];
        double v2 = p3[i] - p1[i];
        dot += v1 * v2;
        lenA += v1 * v1;
        lenB += v2 * v2;
    }
    return 180.0 * acos(dot / sqrt(lenA * lenB)) / M_PI;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n > 20) {
        cout << 0 << "\n";
        return 0;
    }
    vector<vector<int>> pts(n, vector<int>(5));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 5; j++) {
            cin >> pts[i][j];
        }
    }
    vector<int> indices;
    for (int i = 0; i < n; i++) {
        bool skip = false;
        for (int j = 0; j < n; j++) {
            if (i != j) {
                for (int k = j + 1; k < n; k++) {
                    if (i != k) {
                        if (calculateAngle(pts[i], pts[j], pts[k]) < 90) {
                            skip = true;
                            break;
                        }
                    }
                }
                if (skip) break;
            }
        }
        if (!skip) {
            indices.push_back(i + 1);
        }
    }
    cout << (int)indices.size() << "\n";
    for (int idx : indices) {
        cout << idx << "\n";
    }
    return 0;
}
